private void fill() throws IOException {
    if (available() == 0 && buffered < buffer.length && stream != null) {
        int n = stream.read(buffer, buffered, buffer.length - buffered);
        if (n != -1) {
            buffered += n;
        } else {
            close();
        }
    }
}
